/* @lc app=leetcode id=2408 lang=kotlin */ class SQL(names: List<String>, columns: List<Int>, val c: HashMap<String, Int> = HashMap(), val nx: HashMap<String, Int> = HashMap(), val r: HashMap<String, java.util.TreeMap<Int, List<String>>> = HashMap(), val init: Unit = names.indices.forEach { i -> c.put(names[i], columns[i]).also { nx[names[i]] = 1 }.also { r[names[i]] = java.util.TreeMap() } }) { fun ins(name: String, row: List<String>): Boolean = c[name] == row.size && (nx.merge(name, 1) { a, b -> a + b }!! - 1).let { r[name]!![it] = row }.let { true } fun rmv(name: String, rowId: Int) { r[name]?.remove(rowId) } fun sel(name: String, rowId: Int, columnId: Int): String = r[name]?.get(rowId)?.getOrNull(columnId - 1) ?: "<null>" fun exp(name: String): List<String> = r[name]?.entries?.map { (k, v) -> "$k," + v.joinToString(",") } ?: listOf() }